// Generated by Decentraland Studio. Do not edit: this copy is kept in sync with your editor version.
// The rules of carrying, shared by the Multiplayer Server (which decides) and each client (which predicts):
// who holds what, what sits on which station, and how station work turns one kind into another.
// SDK-free, so the server, the prediction and the tests run the same code.
import { zoneKey } from './zoneRegistry'

export interface Vec3 { x: number; y: number; z: number }

export type ItemAt = 'hand' | 'station' | 'floor' | 'gone'

/**
 * One item away from its home. A placed single item that is absent from `items` is at home; an endless source
 * mints a new id (`<source>#<n>`) per pick.
 */
export interface ItemRow {
  kind: string
  at: ItemAt
  /** hand: the holder's wallet */
  who?: string
  /** station: the station id */
  station?: string
  /** floor: where it rests */
  pos?: Vec3
  /** floor after a throw: where it left the hand */
  from?: Vec3
  /** floor after a throw: launch time; gone: when it was used up (game.now() ms) */
  t?: number
}

/** `work` is banked progress in ms; while `since` is set, progress also grows by now - since. */
export interface StationRow { item?: string; work: number; by?: string; since?: number }

export interface CarryState { items: Record<string, ItemRow>; stations: Record<string, StationRow>; n: number }

export interface SourceRule { kind: string; endless: boolean; returnMs: number }
export interface Recipe { out: string; ms: number }
export type StationMode = 'counter' | 'hold' | 'timed'
export interface StationRule {
  mode: StationMode
  /** kind keys this station takes; empty takes anything */
  accepts: string[]
  /** input kind key → output */
  recipes: Record<string, Recipe>
  /** comboKey(a, b) → output kind */
  combines: Record<string, string>
}
export interface CarryRules { sources: Record<string, SourceRule>; stations: Record<string, StationRule> }

export type CarryAction =
  | { type: 'pick'; item: string }
  | { type: 'drop'; pos: Vec3 }
  | { type: 'throw'; from: Vec3; to: Vec3 }
  | { type: 'put'; station: string }
  | { type: 'take'; station: string }
  | { type: 'work'; station: string; on: boolean }

export type CarryEventType = 'pick' | 'drop' | 'throw' | 'put' | 'take' | 'combine' | 'done' | 'give' | 'used' | 'return'

export interface CarryEvent {
  type: CarryEventType
  item: string
  kind: string
  player?: string
  station?: string
  /** combine and done: the kind before */
  was?: string
}

export interface CarryResult { state: CarryState; accepted: boolean; message: string; events: CarryEvent[] }

export const THROW_MS = 700
export const MAX_THROW_M = 8

export const kindKey = zoneKey

export function comboKey(a: string, b: string): string {
  return [kindKey(a), kindKey(b)].sort().join('+')
}

export function freshCarry(n = 0): CarryState {
  return { items: {}, stations: {}, n }
}

/** The item a player holds, or null. */
export function heldItem(state: CarryState, player: string): { item: string; kind: string } | null {
  for (const [item, row] of Object.entries(state.items)) {
    if (row.at === 'hand' && row.who === player) return { item, kind: row.kind }
  }
  return null
}

export function recipeFor(rule: StationRule | undefined, kind: string): Recipe | null {
  return rule?.recipes[kindKey(kind)] ?? null
}

/** The source a minted or placed item came from. */
export function sourceOf(item: string): string {
  const hash = item.indexOf('#')
  return hash < 0 ? item : item.slice(0, hash)
}

/** Station progress, 0 to 1. */
export function stationProgress(row: StationRow | undefined, recipeMs: number, now: number): number {
  if (row === undefined || recipeMs <= 0) return 0
  const ms = row.work + (row.since === undefined ? 0 : Math.max(0, now - row.since))
  return Math.min(1, Math.max(0, ms / recipeMs))
}

function deny(state: CarryState, message = ''): CarryResult {
  return { state, accepted: false, message, events: [] }
}

function ok(state: CarryState, events: CarryEvent[]): CarryResult {
  return { state, accepted: true, message: '', events }
}

// A placed single item that is used up waits as 'gone' so it can come back; anything minted simply ends.
function consumed(items: Record<string, ItemRow>, item: string, kind: string, rules: CarryRules, now: number): void {
  const source = rules.sources[item]
  if (source !== undefined && !source.endless) items[item] = { kind, at: 'gone', t: now }
  else delete items[item]
}

function timedStart(rule: StationRule, kind: string, now: number): number | undefined {
  return rule.mode === 'timed' && recipeFor(rule, kind) !== null ? now : undefined
}

export function applyCarry(state: CarryState, action: CarryAction, player: string, rules: CarryRules, now: number): CarryResult {
  const held = heldItem(state, player)
  const items = { ...state.items }
  const stations = { ...state.stations }
  if (action.type === 'pick') {
    if (held !== null) return deny(state, 'Your hands are full')
    const source = rules.sources[action.item]
    if (source !== undefined && source.endless) {
      const n = state.n + 1
      const item = `${action.item}#${n}`
      items[item] = { kind: source.kind, at: 'hand', who: player }
      return ok({ items, stations, n }, [{ type: 'pick', item, kind: source.kind, player }])
    }
    const row = state.items[action.item]
    if (row === undefined && source === undefined) return deny(state, 'That is gone')
    if (row !== undefined && row.at !== 'floor') return deny(state, row.at === 'gone' ? 'That is gone' : 'Someone else has it')
    const kind = row?.kind ?? source!.kind
    items[action.item] = { kind, at: 'hand', who: player }
    return ok({ ...state, items, stations }, [{ type: 'pick', item: action.item, kind, player }])
  }
  if (action.type === 'drop' || action.type === 'throw') {
    if (held === null) return deny(state)
    items[held.item] = action.type === 'drop'
      ? { kind: held.kind, at: 'floor', pos: action.pos }
      : { kind: held.kind, at: 'floor', pos: action.to, from: action.from, t: now }
    return ok({ ...state, items, stations }, [{ type: action.type, item: held.item, kind: held.kind, player }])
  }
  const rule = rules.stations[action.station]
  if (rule === undefined) return deny(state)
  const row = state.stations[action.station] ?? { work: 0 }
  const onIt = row.item === undefined ? undefined : state.items[row.item]
  if (action.type === 'put') {
    if (held === null) return deny(state)
    if (row.item !== undefined && onIt !== undefined) {
      const out = rule.combines[comboKey(onIt.kind, held.kind)]
      if (out === undefined) return deny(state, 'Something is already here')
      consumed(items, held.item, held.kind, rules, now)
      items[row.item] = { ...onIt, kind: out }
      stations[action.station] = { item: row.item, work: 0, since: timedStart(rule, out, now) }
      return ok({ ...state, items, stations }, [
        { type: 'combine', item: row.item, kind: out, was: onIt.kind, player, station: action.station }
      ])
    }
    if (rule.accepts.length > 0 && !rule.accepts.includes(kindKey(held.kind))) return deny(state, `${held.kind} does not go here`)
    items[held.item] = { kind: held.kind, at: 'station', station: action.station }
    stations[action.station] = { item: held.item, work: 0, since: timedStart(rule, held.kind, now) }
    return ok({ ...state, items, stations }, [{ type: 'put', item: held.item, kind: held.kind, player, station: action.station }])
  }
  if (action.type === 'take') {
    if (held !== null) return deny(state, 'Your hands are full')
    if (row.item === undefined || onIt === undefined) return deny(state, 'Nothing to take')
    items[row.item] = { kind: onIt.kind, at: 'hand', who: player }
    stations[action.station] = { work: 0 }
    return ok({ ...state, items, stations }, [{ type: 'take', item: row.item, kind: onIt.kind, player, station: action.station }])
  }
  if (rule.mode !== 'hold') return deny(state)
  if (action.on) {
    if (row.item === undefined || onIt === undefined) return deny(state, 'Put something here first')
    if (recipeFor(rule, onIt.kind) === null) return deny(state, `Nothing to do with ${onIt.kind} here`)
    if (row.by === player) return deny(state)
    if (row.by !== undefined) return deny(state, 'Someone is already working here')
    stations[action.station] = { ...row, by: player, since: now }
    return ok({ ...state, items, stations }, [])
  }
  if (row.by !== player) return deny(state)
  stations[action.station] = { item: row.item, work: row.work + Math.max(0, now - (row.since ?? now)) }
  return ok({ ...state, items, stations }, [])
}

/**
 * Server: advances every station and brings used-up single items home. `near` answers whether a worker is still at
 * the station; a hold worker who walked away keeps the progress made so far.
 */
export function tickCarry(state: CarryState, rules: CarryRules, now: number, near: (player: string, station: string) => boolean):
  { state: CarryState; events: CarryEvent[]; changed: boolean } {
  const items = { ...state.items }
  const stations = { ...state.stations }
  const events: CarryEvent[] = []
  let changed = false
  for (const [station, row] of Object.entries(state.stations)) {
    const rule = rules.stations[station]
    const onIt = row.item === undefined ? undefined : state.items[row.item]
    const recipe = onIt === undefined ? null : recipeFor(rule, onIt.kind)
    if (rule === undefined || row.item === undefined || onIt === undefined || recipe === null) {
      if (row.by !== undefined || row.since !== undefined) {
        stations[station] = { item: onIt === undefined ? undefined : row.item, work: 0 }
        changed = true
      }
      continue
    }
    if (rule.mode === 'hold' && row.by !== undefined && !near(row.by, station)) {
      stations[station] = { item: row.item, work: row.work + Math.max(0, now - (row.since ?? now)) }
      changed = true
      continue
    }
    if (stationProgress(row, recipe.ms, now) < 1) continue
    items[row.item] = { ...onIt, kind: recipe.out }
    stations[station] = { item: row.item, work: 0, since: timedStart(rule, recipe.out, now) }
    events.push({ type: 'done', item: row.item, kind: recipe.out, was: onIt.kind, station, player: row.by })
    changed = true
  }
  for (const [item, row] of Object.entries(state.items)) {
    const source = rules.sources[item]
    if (row.at !== 'gone' || source === undefined || source.returnMs <= 0) continue
    if (now - (row.t ?? now) < source.returnMs) continue
    delete items[item]
    events.push({ type: 'return', item, kind: row.kind })
    changed = true
  }
  return changed ? { state: { ...state, items, stations }, events, changed } : { state, events, changed }
}

/** A player left: what they held lands where they were (or goes home), and their station work stops. */
export function leaveCarry(state: CarryState, player: string, at: Vec3 | null, now: number): CarryState {
  const held = heldItem(state, player)
  const items = { ...state.items }
  const stations = { ...state.stations }
  if (held !== null) {
    if (at !== null) items[held.item] = { kind: held.kind, at: 'floor', pos: at }
    else delete items[held.item]
  }
  for (const [station, row] of Object.entries(state.stations)) {
    if (row.by === player) stations[station] = { item: row.item, work: row.work + Math.max(0, now - (row.since ?? now)) }
  }
  return { ...state, items, stations }
}

/** Server: puts a new item of `kind` in a player's empty hand. */
export function giveCarry(state: CarryState, player: string, kind: string): CarryResult {
  if (heldItem(state, player) !== null) return deny(state, 'Your hands are full')
  const n = state.n + 1
  const item = `give#${n}`
  return ok({ ...state, n, items: { ...state.items, [item]: { kind, at: 'hand', who: player } } },
    [{ type: 'give', item, kind, player }])
}

/** Server: removes what a player holds (a delivery, a key used on a door). */
export function useHeld(state: CarryState, player: string, rules: CarryRules, now: number): CarryResult {
  const held = heldItem(state, player)
  if (held === null) return deny(state)
  const items = { ...state.items }
  consumed(items, held.item, held.kind, rules, now)
  return ok({ ...state, items }, [{ type: 'used', item: held.item, kind: held.kind, player }])
}

/** Server: replaces what sits on a station with a new item of `kind`, or clears it with null. */
export function setStationKind(state: CarryState, station: string, kind: string | null, rules: CarryRules, now: number): CarryResult {
  const rule = rules.stations[station]
  if (rule === undefined) return deny(state)
  const row = state.stations[station] ?? { work: 0 }
  const items = { ...state.items }
  const events: CarryEvent[] = []
  const old = row.item === undefined ? undefined : items[row.item]
  if (row.item !== undefined && old !== undefined) {
    consumed(items, row.item, old.kind, rules, now)
    events.push({ type: 'used', item: row.item, kind: old.kind, station })
  }
  if (kind === null) return ok({ ...state, items, stations: { ...state.stations, [station]: { work: 0 } } }, events)
  const n = state.n + 1
  const item = `give#${n}`
  items[item] = { kind, at: 'station', station }
  events.push({ type: 'give', item, kind, station })
  return ok({ ...state, n, items, stations: { ...state.stations, [station]: { item, work: 0, since: timedStart(rule, kind, now) } } }, events)
}

function isNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value)
}

function readVec(value: unknown): Vec3 | undefined {
  if (typeof value !== 'object' || value === null) return undefined
  const v = value as Record<string, unknown>
  return isNumber(v.x) && isNumber(v.y) && isNumber(v.z) ? { x: v.x, y: v.y, z: v.z } : undefined
}

const AT: ItemAt[] = ['hand', 'station', 'floor', 'gone']

/** Validates synced or requested data; malformed rows are dropped, never trusted. */
export function readCarry(value: unknown): CarryState {
  const out = freshCarry()
  if (typeof value !== 'object' || value === null) return out
  const raw = value as Record<string, unknown>
  if (isNumber(raw.n) && raw.n >= 0) out.n = Math.floor(raw.n)
  const items = typeof raw.items === 'object' && raw.items !== null ? raw.items as Record<string, unknown> : {}
  for (const [id, entry] of Object.entries(items)) {
    if (typeof entry !== 'object' || entry === null) continue
    const row = entry as Record<string, unknown>
    if (typeof row.kind !== 'string' || !AT.includes(row.at as ItemAt)) continue
    const item: ItemRow = { kind: row.kind, at: row.at as ItemAt }
    if (item.at === 'hand') {
      if (typeof row.who !== 'string') continue
      item.who = row.who
    }
    if (item.at === 'station') {
      if (typeof row.station !== 'string') continue
      item.station = row.station
    }
    if (item.at === 'floor') {
      const pos = readVec(row.pos)
      if (pos === undefined) continue
      item.pos = pos
      const from = readVec(row.from)
      if (from !== undefined && isNumber(row.t)) {
        item.from = from
        item.t = row.t
      }
    }
    if (item.at === 'gone' && isNumber(row.t)) item.t = row.t
    out.items[id] = item
  }
  const stations = typeof raw.stations === 'object' && raw.stations !== null ? raw.stations as Record<string, unknown> : {}
  for (const [id, entry] of Object.entries(stations)) {
    if (typeof entry !== 'object' || entry === null) continue
    const row = entry as Record<string, unknown>
    const station: StationRow = { work: isNumber(row.work) && row.work > 0 ? row.work : 0 }
    if (typeof row.item === 'string' && out.items[row.item]?.at === 'station') station.item = row.item
    if (typeof row.by === 'string') station.by = row.by
    if (isNumber(row.since)) station.since = row.since
    out.stations[id] = station
  }
  return out
}

/** A request body as an action, or null for anything malformed. */
export function readAction(value: unknown): CarryAction | null {
  if (typeof value !== 'object' || value === null) return null
  const raw = value as Record<string, unknown>
  if (raw.type === 'pick' && typeof raw.item === 'string') return { type: 'pick', item: raw.item }
  if (raw.type === 'drop') {
    const pos = readVec(raw.pos)
    return pos === undefined ? null : { type: 'drop', pos }
  }
  if (raw.type === 'throw') {
    const from = readVec(raw.from)
    const to = readVec(raw.to)
    return from === undefined || to === undefined ? null : { type: 'throw', from, to }
  }
  if (typeof raw.station !== 'string') return null
  if (raw.type === 'put' || raw.type === 'take') return { type: raw.type, station: raw.station }
  if (raw.type === 'work' && typeof raw.on === 'boolean') return { type: 'work', station: raw.station, on: raw.on }
  return null
}

/** Keeps a throw's landing spot within MAX_THROW_M of where it left the hand. */
export function clampThrow(from: Vec3, to: Vec3): Vec3 {
  const dx = to.x - from.x
  const dz = to.z - from.z
  const d = Math.hypot(dx, dz)
  if (d <= MAX_THROW_M) return to
  const k = MAX_THROW_M / d
  return { x: from.x + dx * k, y: to.y, z: from.z + dz * k }
}

/** Where a thrown item is at `now`: a parabola from `from` to `pos`, landed once THROW_MS has passed. */
export function flightPosition(row: ItemRow, now: number): Vec3 | null {
  if (row.pos === undefined) return null
  if (row.from === undefined || row.t === undefined) return row.pos
  const k = Math.min(1, Math.max(0, (now - row.t) / THROW_MS))
  const lerp = (a: number, b: number) => a + (b - a) * k
  return { x: lerp(row.from.x, row.pos.x), y: lerp(row.from.y, row.pos.y) + 4 * 1.2 * k * (1 - k), z: lerp(row.from.z, row.pos.z) }
}

function split(text: string): string[] {
  return text.split(/[,;\n]/).map((part) => part.trim()).filter(Boolean)
}

/** "Tomato > Chopped Tomato, Lettuce > Chopped Lettuce" → recipes keyed by input kind. */
export function parseTurns(text: string, ms: number): Record<string, Recipe> {
  const out: Record<string, Recipe> = {}
  for (const part of split(text)) {
    const [input, output] = part.split(/->|→|>/).map((side) => side.trim())
    if (input && output) out[kindKey(input)] = { out: output, ms }
  }
  return out
}

/** "Bun + Patty > Burger" → combine table keyed by comboKey. */
export function parseCombines(text: string): Record<string, string> {
  const out: Record<string, string> = {}
  for (const part of split(text)) {
    const [inputs, output] = part.split(/->|→|>/).map((side) => side.trim())
    const pair = (inputs ?? '').split('+').map((side) => side.trim())
    if (pair.length === 2 && pair[0] && pair[1] && output) out[comboKey(pair[0], pair[1])] = output
  }
  return out
}

export function parseKinds(text: string): string[] {
  return split(text).map(kindKey)
}
